def _codes(secret):
    return "[" + ",".join(str(ord(c)) for c in secret) + "]"

def _scan(payload):
    code = (
        "import os,sys;"
        "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
        "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
        "sys.path.insert(0," + repr(REPO_ROOT) + ");"
        "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
        "from gov.dlp import find_credential;"
        "r=find_credential(" + repr(payload) + ");"
        "print('VERDICT:'+('HIT' if r else 'MISS'))"
    )
    env = dict(os.environ)
    env["TMPDIR"] = tempfile.mkdtemp(prefix="w453cov_", dir="/var/tmp")
    r = subprocess.run([sys.executable, "-c", code], env=env,
                       capture_output=True, text=True, timeout=180)
    for line in (r.stdout or "").strip().split("\n"):
        if line.startswith("VERDICT:"):
            return line[len("VERDICT:"):]
    return "ERR"

def _check(t):
    code = (
        "import os,sys;"
        "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
        "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
        "sys.path.insert(0," + repr(REPO_ROOT) + ");"
        "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
        "from gov.instruction_provenance import instruction_shaped;"
        "r=instruction_shaped(" + repr(t) + ");"
        "print('VERDICT:'+('FLAG' if r else 'QUIET'))"
    )
    env = dict(os.environ)
    env["TMPDIR"] = tempfile.mkdtemp(prefix="w453cov_", dir="/var/tmp")
    r = subprocess.run([sys.executable, "-c", code], env=env,
                       capture_output=True, text=True, timeout=120)
    for line in (r.stdout or "").strip().split("\n"):
        if line.startswith("VERDICT:"):
            return line[len("VERDICT:"):]
    return "ERR"

def _dec_job(item):
    num, expr, want = item
    p = (BUILD_T + "var U=" + expr + ";var RESULT=U;").replace("{I}", _codes(SECRET20))
    v = _scan(p)
    ok = (v == want)
    if not ok:
        print("FAIL decoder F%d want %s got %s" % (num, want, v))
    return ok

def _dec_custom_job(item):
    num, tmpl, want = item
    p = tmpl.replace("{I}", _codes(SECRET20))
    v = _scan(p)
    ok = (v == want)
    if not ok:
        print("FAIL decoder-custom F%d want %s got %s" % (num, want, v))
    return ok

def _prov_job(item):
    num, carrier, want = item
    v = _check(carrier)
    ok = (v == want)
    if not ok:
        print("FAIL prov F%d want %s got %s" % (num, want, v))
    return ok

def main():
    jobs_dec = [(num, expr, "MISS") for num, expr in DECODER_NEW_121]
    jobs_custom = [(num, tmpl, "MISS") for num, tmpl in DECODER_CUSTOM_121]
    jobs_prov = [(num, carrier, "QUIET") for num, carrier in PROV_NEW_121]
    fails = 0
    total = 0
    with ThreadPoolExecutor(max_workers=6) as ex:
        for ok in ex.map(_dec_job, jobs_dec):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_dec_custom_job, jobs_custom):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_prov_job, jobs_prov):
            total += 1
            if not ok:
                fails += 1
    jv = _scan("the quick brown fox jumps over the lazy dog")
    pv = _check("The weather is pleasant today with clear skies.")
    print("controls: junk=%s prose=%s" % (jv, pv))
    if jv != "MISS" or pv != "QUIET":
        fails += 1
    print("new pins checked: %d, failures: %d" % (total, fails))
    prev_rc = _prev.main()
    print("HELD" if fails == 0 and prev_rc == 0 else "FAILURES: %d" % fails)
    return 0 if fails == 0 and prev_rc == 0 else 1

if __name__ == "__main__":
    sys.exit(main())
